import org.junit.jupiter.api.*;

import static org.junit.jupiter.api.Assertions.*;

public class Main {
    public static void main(String[] args) {
        JalankanTest.kelas(GudangTest.class);
    }
}

class GudangTest {
    static Gudang gudang = new Gudang();

    @Test
    void barangBaruStokNol() {
        gudang.daftarkan("Pensil");
        assertEquals(0, gudang.stok("Pensil"));
    }

    @Test
    void masukMenambahStok() {
        gudang.daftarkan("Pensil");
        gudang.masuk("Pensil", 10);
        assertEquals(10, gudang.stok("Pensil"));
    }

    @Test
    void jumlahJenisBarang() {
        gudang.daftarkan("Buku");
        assertEquals(1, gudang.jumlahJenis());
    }
}

class Gudang {
    private final Map<String, Integer> stok = new HashMap<>();

    void daftarkan(String nama) {
        stok.putIfAbsent(nama, 0);
    }

    void masuk(String nama, int jumlah) {
        stok.put(nama, stok.get(nama) + jumlah);
    }

    int stok(String nama) {
        return stok.get(nama);
    }

    int jumlahJenis() {
        return stok.size();
    }
}

